import fnmatch, subprocess

files = subprocess.run(["git", "ls-files"], capture_output=True, text=True, check=True).stdout.splitlines()
ignore = ["galaxy.yml"]
with open("galaxy.yml") as f:
    in_block = False
    for line in f:
        if line.startswith("build_ignore:"):
            in_block = True
            continue
        if in_block:
            if line.startswith("  - "):
                ignore.append(line.strip()[2:])
            else:
                break

def is_ignored(path, patterns):
    for p in patterns:
        if p.endswith("/"):
            if path == p.rstrip("/") or path.startswith(p):
                return p
        elif fnmatch.fnmatch(path, p) or path == p:
            return p
    return None

included, excluded = [], []
for f in files:
    hit = is_ignored(f, ignore)
    (excluded if hit else included).append((f, hit))

print("Would be EXCLUDED from tarball:")
for f, hit in excluded:
    print(f"  {f}  (matched: {hit})")
print("\nWould be INCLUDED in tarball:")
for f, _ in included:
    print(f"  {f}")
EOF
